OWNER_LABEL_PATTERN = re.compile(r"(?P<article>(?i:a|an|the|that|its|each)\s+)?(?P<modifiers>(?:(?i:"+MODIFIER_PATTERN+r")\s+)*)(?P<noun>(?i:"+NOUN_PATTERN+r"))\s+A\b(?P<possessive>'s)?")
def naturalize(text):
    def replace(match):
        article=(match.group('article') or '').lower()
        modifiers=(match.group('modifiers') or '').lower()
        noun=match.group('noun').lower()
        prefix=text[:match.start()]
        possessed=bool(re.search(r"(?:\b(?:his|her|their|our|your|its)|\b\w+'s)\s*$",prefix))
        if noun=='polo': noun='polo top'
        if not article and not modifiers and not possessed and noun=='top': noun='same top'
        if not article and not modifiers and not possessed and noun=='inner top': noun='separate inner top'
        result=(article or ('' if possessed else 'the '))+modifiers+noun
        if match.group('possessive'): result += "'" if noun in {'shorts','trousers','sandals','shoes','socks','leg warmers','flat shoes'} else "'s"
        return result
    result=OWNER_LABEL_PATTERN.sub(replace,text)
    result=' '.join(result.split())
    if result:result=result[0].upper()+result[1:]
    assert not re.search(r"[a-z] A\b",result), result
    return result
